//! Root hashes and node spends generated by Cloud Wallet's implementation, which created the bags already on chain.
//!
//! Each fixture lists its payments in an arbitrary order, since the bag sorts them. The expected edges are every
//! (parent, child) pair of coins in the bag, keyed by full puzzle hash, along with hashes of the serialized parent
//! puzzle reveal and inner solution. The digest is the SHA-256 of the sorted edges, one per line.

use anyhow::Result;
use chia_protocol::{Bytes32, Coin};
use chia_puzzle_types::{LineageProof, cat::CatSolution};
use chia_sdk_driver::{
    BagAsset, BagCoin, BagFormat, BagPayment, Cat, ClawbackV2, SecureTheBag, SpendContext,
};
use chia_sha2::Sha256;
use clvmr::{NodePtr, serde::node_to_bytes};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    name: String,
    asset: Asset,
    leaf_width: Option<usize>,
    expected: Expected,
    payments: Vec<Payment>,
}

#[derive(Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Asset {
    Xch,
    Cat {
        asset_id: String,
    },
    RevocableCat {
        asset_id: String,
        hidden_puzzle_hash: String,
    },
}

#[derive(Deserialize)]
struct Expected {
    root_hash: String,
    total_amount: String,
    leaf_width: usize,
    node_count: usize,
    edge_count: usize,
    edges_digest: String,
    edges: Option<Vec<Edge>>,
}

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord, Deserialize)]
struct Edge {
    parent: String,
    child: String,
    amount: String,
    parent_puzzle_reveal: String,
    parent_inner_solution: String,
}

#[derive(Deserialize)]
struct Payment {
    puzzle_hash: String,
    amount: String,
    clawback: Option<Clawback>,
}

#[derive(Deserialize)]
struct Clawback {
    sender_puzzle_hash: String,
    seconds: String,
    hinted: bool,
}

fn bytes32(value: &str) -> Result<Bytes32> {
    Ok(Bytes32::new(hex::decode(value)?.try_into().map_err(
        |_| anyhow::anyhow!("expected 32 bytes: {value}"),
    )?))
}

fn sha256(data: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data);
    hex::encode(hasher.finalize())
}

impl Asset {
    fn to_bag_asset(&self) -> Result<BagAsset> {
        Ok(match self {
            Self::Xch => BagAsset::Xch,
            Self::Cat { asset_id } => BagAsset::Cat {
                asset_id: bytes32(asset_id)?,
            },
            Self::RevocableCat {
                asset_id,
                hidden_puzzle_hash,
            } => BagAsset::RevocableCat {
                asset_id: bytes32(asset_id)?,
                hidden_puzzle_hash: bytes32(hidden_puzzle_hash)?,
            },
        })
    }
}

impl Payment {
    fn to_bag_payment(&self) -> Result<BagPayment> {
        let puzzle_hash = bytes32(&self.puzzle_hash)?;
        let amount = self.amount.parse()?;

        Ok(match &self.clawback {
            Some(clawback) => BagPayment::clawback(ClawbackV2::new(
                bytes32(&clawback.sender_puzzle_hash)?,
                puzzle_hash,
                clawback.seconds.parse()?,
                amount,
                clawback.hinted,
            )),
            None => BagPayment::new(puzzle_hash, amount),
        })
    }
}

/// Spends each node of the bag with a placeholder coin, to compare the puzzle reveal and inner solution.
fn edges(bag: &SecureTheBag) -> Result<Vec<Edge>> {
    let asset = bag.asset();
    let mut edges = Vec::new();

    for (&puzzle_hash, node) in bag.nodes() {
        let coin = Coin::new(
            Bytes32::default(),
            asset.puzzle_hash(puzzle_hash),
            node.amount,
        );

        let bag_coin = match asset.cat_info(puzzle_hash) {
            Some(info) => BagCoin::Cat(Cat::new(
                coin,
                Some(LineageProof {
                    parent_parent_coin_info: Bytes32::default(),
                    parent_inner_puzzle_hash: Bytes32::default(),
                    parent_amount: 0,
                }),
                info,
            )),
            None => BagCoin::Xch(coin),
        };

        let mut ctx = SpendContext::new();
        bag.spend_node(&mut ctx, bag_coin)?;
        let coin_spends = ctx.take();
        assert_eq!(coin_spends.len(), 1);
        let coin_spend = &coin_spends[0];

        let inner_solution = match bag_coin {
            BagCoin::Xch(_) => coin_spend.solution.to_vec(),
            BagCoin::Cat(_) => {
                let solution = ctx.alloc(&coin_spend.solution)?;
                let solution = ctx.extract::<CatSolution<NodePtr>>(solution)?;
                node_to_bytes(&ctx, solution.inner_puzzle_solution)?
            }
        };

        let parent_puzzle_reveal = sha256(&coin_spend.puzzle_reveal);
        let parent_inner_solution = sha256(&inner_solution);

        for child in &node.children {
            edges.push(Edge {
                parent: hex::encode(coin.puzzle_hash),
                child: hex::encode(asset.puzzle_hash(child.puzzle_hash())),
                amount: child.amount().to_string(),
                parent_puzzle_reveal: parent_puzzle_reveal.clone(),
                parent_inner_solution: parent_inner_solution.clone(),
            });
        }
    }

    edges.sort();

    Ok(edges)
}

fn edges_digest(edges: &[Edge]) -> String {
    let lines: String = edges
        .iter()
        .map(|edge| {
            format!(
                "{} {} {} {} {}\n",
                edge.parent,
                edge.child,
                edge.amount,
                edge.parent_puzzle_reveal,
                edge.parent_inner_solution
            )
        })
        .collect();
    sha256(lines.as_bytes())
}

#[test]
fn legacy_golden_vectors() -> Result<()> {
    let fixtures: Vec<Fixture> = serde_json::from_str(include_str!("data/legacy.json"))?;

    for fixture in fixtures {
        let name = &fixture.name;
        let format = BagFormat::Legacy {
            leaf_width: fixture.leaf_width,
        };
        let payments = fixture
            .payments
            .iter()
            .map(Payment::to_bag_payment)
            .collect::<Result<Vec<_>>>()?;

        let bag = SecureTheBag::build(format, fixture.asset.to_bag_asset()?, payments.clone())?;
        let expected = &fixture.expected;

        assert_eq!(
            hex::encode(bag.root_hash()),
            expected.root_hash,
            "{name}: root hash"
        );
        assert_eq!(
            bag.total_amount().to_string(),
            expected.total_amount,
            "{name}: total amount"
        );
        assert_eq!(
            format.width(payments.len()),
            expected.leaf_width,
            "{name}: leaf width"
        );
        assert_eq!(bag.nodes().len(), expected.node_count, "{name}: node count");

        let edges = edges(&bag)?;

        if let Some(expected_edges) = &expected.edges {
            assert_eq!(&edges, expected_edges, "{name}: edges");
        }

        assert_eq!(edges.len(), expected.edge_count, "{name}: edge count");
        assert_eq!(
            edges_digest(&edges),
            expected.edges_digest,
            "{name}: edges digest"
        );
    }

    Ok(())
}
